import json, subprocess, tempfile
from pathlib import Path
paths = ["docs/ai-driven-development/aidd-checker.md", "docs/ai-driven-development/aidd-checker-operations.md", "tools/aidd/checker/internal/core/lifecycle.go", "tools/aidd/checker/internal/core/model.go", "tools/aidd/checker/internal/core/core_test.go", "tools/aidd/checker/internal/core/audit_approval_test.go", "tools/aidd/session-metrics/main.go", "tools/aidd/session-metrics/main_test.go", ".agents/skills/retrospective/SKILL.md"]
with tempfile.TemporaryDirectory() as tmp:
    source = Path(tmp) / "paths.json"
    for path in paths + [".agents/skills/audit/SKILL.md", ".github/ISSUE_TEMPLATE/task.md"]:
        source.write_text(json.dumps([path]))
        result = subprocess.run(["/tmp/aidd-1852", "--root", ".", "rules", "--paths", str(source)], check=True, capture_output=True, text=True)
        ids = {rule["id"] for rule in json.loads(result.stdout)}
        if path in paths:
            assert {"policy.retrospective", "ai-driven.workflow", "policy.learning-extraction", "documentation.policy"} <= ids, (path, ids)
        else:
            assert "policy.retrospective" not in ids, (path, ids)
        if path == ".agents/skills/audit/SKILL.md":
            assert "ai-driven.audit" in ids, (path, ids)
        print(path + ": passed")
